PLAN_B64=''
AUTH_B64=''
PLAN_SHA='a051a3f06ab885e258f1a2fa4f7ea0431999f095dd6f5cd369200d4cfe13a265'
"""Invoke the unchanged, independently reviewed D03 runtime once in its approved window."""
import base64,datetime as dt,hashlib,json,os,pathlib,platform,signal,socket,subprocess,sys
def now():return dt.datetime.now(dt.timezone.utc)
def write(path,value):
    with path.open('x',encoding='utf-8') as f:json.dump(value,f,indent=2);f.write('\n')
os.umask(0o077)
assert socket.gethostname()=='cicd-runner01' and os.getuid()==1000 and platform.machine()=='x86_64'
home=pathlib.Path('/home/server01_cicd-runner');bundle=home/'FDS_D03_Preparation_6531b51c9915';decisions=home/'FDS_D03_Decisions_202610150030'
plan_raw=base64.b64decode(PLAN_B64);auth_raw=base64.b64decode(AUTH_B64)
assert (decisions/'plan.json').read_bytes()==plan_raw and (decisions/'authorization.json').read_bytes()==auth_raw
assert hashlib.sha256(plan_raw).hexdigest()==PLAN_SHA
for line in (bundle/'SHA256SUMS').read_text().splitlines():
    digest,rel=line.split('  ',1);p=bundle/rel
    assert p.resolve().is_relative_to(bundle) and not p.is_symlink() and hashlib.sha256(p.read_bytes()).hexdigest()==digest
sys.path.insert(0,str(bundle/'source/tools/regression'))
import d03_lab
plan=d03_lab.read_plan(decisions/'plan.json',PLAN_SHA);auth=json.loads(auth_raw)
end=d03_lab.authorize(plan,auth,now())
assert json.loads((home/'FDS_D03_SupplyValidation_202610142110/result.json').read_bytes())['status']=='SUPPLY_VERIFIED_BY_OCI_DESCRIPTOR'
# Recheck actual image IDs now; the old supply record alone is not a fresh observation.
for role,image in d03_lab.IMAGES.items():
    image_info=json.loads(subprocess.check_output(['podman','image','inspect',image],timeout=10))[0]
    identity='sha256:'+image_info['Id'].removeprefix('sha256:')
    expected='sha256:5f7659016ef769811a0fdc349c9cad11f520dc7e147633bb1025e499002d9cd2' if role=='db' else image
    assert identity==expected and image_info['Architecture']=='amd64' and image_info['Os']=='linux','CURRENT_IMAGE_MISMATCH'
    if role=='db':assert image in image_info['RepoDigests'] and image_info['Config']['User']=='26'

workers=[]
for p in pathlib.Path('/proc').glob('[0-9]*/comm'):
    try:
        if p.read_text().strip()=='Runner.Worker':workers.append(int(p.parent.name))
    except (FileNotFoundError,ProcessLookupError):pass
assert not workers,'RUNNER_WORKER_ACTIVE'
assert json.loads(subprocess.check_output(['podman','ps','-a','--format','json'],timeout=10))==[],'CONTAINERS_EXIST'
mem=int(next(x.split()[1] for x in pathlib.Path('/proc/meminfo').read_text().splitlines() if x.startswith('MemAvailable:')))
assert mem>2*1024*1024,'MEMORY_INSUFFICIENT'
assert not (home/'FDS_D03_Claims/202610150030.json').exists() and not (home/'FDS_D03_202610150030').exists(),'RUN_ALREADY_CLAIMED'
out=home/'FDS_D03_RuntimeInvocation_202610150030';out.mkdir(mode=0o700)
argv=['/usr/bin/python3','-B',str(bundle/'source/tools/regression/d03_lab.py'),'run',str(decisions/'plan.json'),str(home/'FDS_D03_202610150030'),'--plan-sha',PLAN_SHA,'--authorization',str(decisions/'authorization.json')]
receipt={'started_at_utc':now().isoformat(),'argv':argv,'cwd':str(bundle/'source'),'memory_available_kib':mem,'worker_count':0,'container_count':0,'plan_sha256':PLAN_SHA,'automatic_retry':False}
write(out/'intent.json',receipt)
with (out/'stdout.txt').open('xb') as stdout,(out/'stderr.txt').open('xb') as stderr:
    d03_lab.authorize(plan,auth,now())
    p=subprocess.Popen(argv,cwd=bundle/'source',stdout=stdout,stderr=stderr)
    write(out/'process.json',{'pid':p.pid,'started_at_utc':now().isoformat()})
    try:rc=p.wait(timeout=min(900,(end-now()).total_seconds()-120))
    except subprocess.TimeoutExpired:
        receipt['supervisor_timeout']=True;p.send_signal(signal.SIGTERM)
        try:rc=p.wait(timeout=max(1,(end-now()).total_seconds()))
        except subprocess.TimeoutExpired:rc=None;receipt['process_still_running']=True
receipt.update(rc=rc,finished_at_utc=now().isoformat(),stdout_sha256=hashlib.sha256((out/'stdout.txt').read_bytes()).hexdigest(),stderr_sha256=hashlib.sha256((out/'stderr.txt').read_bytes()).hexdigest())
write(out/'receipt.json',receipt)
(out/'SHA256SUMS').write_text(''.join(hashlib.sha256(f.read_bytes()).hexdigest()+'  '+f.name+'\n' for f in sorted(out.iterdir()) if f.is_file()))
result_path=home/'FDS_D03_202610150030/result.json'
result=json.loads(result_path.read_bytes()) if result_path.exists() else {'result':'MISSING_RUNTIME_RESULT','no_retry':True}
print(json.dumps({'invocation':receipt,'runtime_result':result,'claim_exists':(home/'FDS_D03_Claims/202610150030.json').exists()}))
